<?php
declare(strict_types=1);
$config=parse_ini_file(dirname(__DIR__).'/.env') ?: parse_ini_file(dirname(__DIR__).'/.env.example');
try{$pdo=new PDO(sprintf('mysql:host=%s;port=%s;dbname=%s;charset=utf8mb4',$config['DB_HOST'],$config['DB_PORT'],$config['DB_DATABASE']),$config['DB_USERNAME'],$config['DB_PASSWORD'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$password=getenv('ADMIN_INITIAL_PASSWORD')?:'TroqueEstaSenha!2026';$pdo->prepare("INSERT IGNORE INTO perfis(nome,slug,created_at,updated_at) VALUES ('Superadministrador','superadministrador',NOW(),NOW())")->execute();foreach(['atletas.visualizar','atletas.criar','atletas.editar','atletas.inativar','atletas.exportar','documentos.visualizar','documentos.enviar','documentos.aprovar','documentos.rejeitar','documentos.excluir','modalidades.gerenciar','equipes.gerenciar','relatorios.visualizar','relatorios.exportar','usuarios.gerenciar','auditoria.visualizar','configuracoes.gerenciar'] as $p)$pdo->prepare('INSERT IGNORE INTO permissoes(chave,descricao) VALUES (?,?)')->execute([$p,$p]);$pdo->prepare('INSERT IGNORE INTO usuarios(nome,email,senha_hash,ativo,deve_alterar_senha,created_at,updated_at) VALUES (?,?,?,?,1,NOW(),NOW())')->execute(['Administrador SIGESP','admin@sigesporte.local',password_hash($password,defined('PASSWORD_ARGON2ID')?PASSWORD_ARGON2ID:PASSWORD_DEFAULT),1]);$pdo->exec('INSERT IGNORE INTO usuarios_perfis SELECT u.id,p.id FROM usuarios u CROSS JOIN perfis p WHERE u.email="admin@sigesporte.local" AND p.slug="superadministrador"');$pdo->exec('INSERT IGNORE INTO perfis_permissoes SELECT r.id,p.id FROM perfis r CROSS JOIN permissoes p WHERE r.slug="superadministrador"');foreach([['Futebol','coletivo'],['Futsal','coletivo'],['Voleibol','coletivo'],['Atletismo','individual']] as [$n,$t])$pdo->prepare('INSERT IGNORE INTO modalidades(nome,tipo,created_at,updated_at) VALUES (?,?,NOW(),NOW())')->execute([$n,$t]);echo "Seed aplicado. Usuário: admin@sigesporte.local\n";}catch(Throwable $e){fwrite(STDERR,"Seed não executado: aplique o schema em um MySQL/MariaDB com pdo_mysql.\n");exit(1);}
